pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: fund the contract with 2 wei, deposit by owner
        vm.deal(address(c), 2 ether);

        // Deploy a helper contract that forwards call value to msg.sender
        Forwarder f = new Forwarder();

        // Non-owner calls sendMoney to forwarder with 1 wei
        address nonOwner = address(0x1);
        vm.deal(nonOwner, 0); // non-owner doesn't need eth
        vm.prank(nonOwner);
        c.sendMoney(address(f), 1, "");

        // In reference, this revert -> non-owner can't call sendMoney; in mutant it succeeds -> 1 wei goes to forwarder which sends to non-owner
        // Now owner calls withdrawAll to drain remaining balance
        address owner = c.owner();
        uint256 balanceBeforeOwner = owner.balance;
        vm.prank(owner);
        c.withdrawAll();
        uint256 balanceAfterOwner = owner.balance;

        // Assert: in reference, sendMoney reverted and only 2 wei goes to owner via withdrawAll => balance increases by 2
        // In mutant, sendMoney succeeded (1 wei to non-owner) and withdrawAll sends 1 wei to owner => balance increases by 1
        assertTrue(balanceAfterOwner - balanceBeforeOwner == 2 ether, "Owner should receive 2 wei in reference (sendMoney reverts)");
    }
}

contract Forwarder {
    fallback() external payable {
        payable(msg.sender).transfer(msg.value);
    }
}

