pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up attacker contract that will reenter
        address attacker = address(0x123);
        vm.deal(attacker, 1 ether);

        // Fund the contract with 1 ether so withdrawAll can transfer
        vm.deal(address(c), 1 ether);

        // Deploy a reentrancy contract (inline)
        // The reentrancy contract calls c.withdrawAll() when it receives a call from sendMoney
        // We'll use a simple attack: deploy a contract that in its receive() calls withdrawAll
        // Simpler: use vm.prank to call sendMoney with a contract that reenters

        // Deploy attacker contract
        ReentrantAttacker re = new ReentrantAttacker(c);
        vm.deal(address(re), 1 ether);

        // The attacker calls sendMoney with re as target, sending 0.5 ether
        // re's fallback will call c.withdrawAll()
        vm.prank(attacker);
        c.sendMoney(address(re), 0.5 ether, abi.encodeWithSignature(""));

        // After the call, the correct contract reverts the inner withdrawAll so depositsCount stays 1
        // The buggy contract allows the reentrant withdrawAll, so depositsCount becomes 2
        bool ok = c.depositsCount() == 1;
        assertTrue(ok);
    }
}

contract ReentrantAttacker {
    C public c;
    constructor(C _c) { c = _c; }
    fallback() external payable {
        if (address(c).balance >= 1 ether) {
            c.withdrawAll();
        }
    }
    receive() external payable {
        if (address(c).balance >= 1 ether) {
            c.withdrawAll();
        }
    }
}

