import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy attacker contract that reenters via receive
        Attacker attacker = new Attacker(address(c));
        // Fund the contract with 1 ether
        vm.deal(address(c), 1 ether);
        // Trigger fallback to increase depositsCount to 1
        (bool ok,) = address(c).call{value: 0}("");
        assertTrue(ok);
        assertEq(c.depositsCount(), 1);
        // Now call sendMoney with 1 ether to attacker, which triggers reentrancy
        vm.prank(c.owner());
        bytes memory payload = abi.encodeWithSelector(attacker.attack.selector);
        try c.sendMoney{value: 1 ether}(address(attacker), 1 ether, payload) {
            // If call succeeds (buggy version), attacker's receive will have called withdrawAll again
        } catch {
            // Revert expected for reference
        }
        // Assert: reference has depositsCount=1, buggy has depositsCount=2
        assertTrue(c.depositsCount() == 1);
    }
}

contract Attacker {
    C public target;
    bool public attacked;
    constructor(address _target) { target = C(_target); }
    receive() external payable {
        if (!attacked) {
            attacked = true;
            target.withdrawAll();
        }
    }
    function attack() external {
        // This function is called via sendMoney's call
    }
}

